package com.ryanjei.orushio.pve.logging;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class AuditLogTest{@TempDir Path temp;@Test void 制御文字をJSONLines向けにescapeする()throws Exception{AuditLog log=new AuditLog(temp);log.record("trace","HTTP\nERROR","CODE\r\t", "say \\\"x");String line=Files.readString(Files.list(temp).findFirst().orElseThrow());assertFalse(line.substring(0,line.length()-1).contains("\n"));assertTrue(line.contains("\\n"));assertTrue(line.contains("\\r\\t"));assertTrue(line.contains("\\\\\\\""));assertTrue(log.healthy());}@Test void 書込み失敗を診断可能にする()throws Exception{Path file=temp.resolve("file");Files.writeString(file,"x");AuditLog log=new AuditLog(file);log.record("t","c","e","o");assertFalse(log.healthy());}}
